const cardPaintVersions=new WeakMap();
function paintProductCard(card,p){const canvas=card.querySelector('canvas'),version=(cardPaintVersions.get(canvas)||0)+1;cardPaintVersions.set(canvas,version);canvas.setAttribute('aria-label',p.title+' · '+(p.style===2?'不带按钮':'带按钮'));composeCard(clone(p),cardTheme()).then(artwork=>{if(cardPaintVersions.get(canvas)!==version)return;const context=canvas.getContext('2d');context.clearRect(0,0,canvas.width,canvas.height);context.drawImage(artwork,0,0);card.classList.remove('asset-error')}).catch(()=>{if(cardPaintVersions.get(canvas)!==version)return;card.classList.add('asset-error');canvas.setAttribute('aria-label','卡片图片加载失败')})}
