async function readGroupFiles(files){
 const target=product();if(!files.length)return;if(files.length<2||files.length>3){toast('请一次选择或拖入 2 至 3 张商品图片');return}
 const version=(groupReadVersions.get(target)||0)+1;groupReadVersions.set(target,version);groupReading.add(target);syncGroupUpload();
 try{const sources=[];for(const file of files){if(!file.type.startsWith('image/')||file.size>8*1024*1024)throw new Error('请选择 8 MB 以内的商品图片');const src=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});sources.push(await prepareProductImage(src))}
 if(groupReadVersions.get(target)!==version)return;groupSources.set(target,sources);
 }catch(error){if(groupReadVersions.get(target)===version)toast(error.message||'商品图片读取失败')}
 finally{if(groupReadVersions.get(target)===version){groupReading.delete(target);syncGroupUpload()}}
}
