groupCompose.title='本地自动排列商品图';groupCompose.onclick=async()=>{const target=product(),sources=groupSources.get(target);if(!sources)return;groupCompose.disabled=true;try{const images=await Promise.all(sources.map(loadCardImage)),canvas=document.createElement('canvas');canvas.width=1000;canvas.height=1000;const c=canvas.getContext('2d'),cell=900/images.length;images.forEach((image,i)=>{const scale=Math.min((cell+50)/image.width,(i===1?900:790)/image.height),w=image.width*scale,h=image.height*scale;c.drawImage(image,50+cell*i+(cell-w)/2,960-h,w,h)});const src=await prepareProductImage(canvas.toDataURL('image/png'));if(groupSources.get(target)===sources&&!groupReading.has(target)&&state.tabs.some(g=>g.products.includes(target)))change(()=>{target.image=src;target.showProduct=true;target.isGroupedProduct=true;target.productScale=1;target.productOffsetX=0;target.productOffsetY=0})}catch(error){toast(error.message||'组品失败')}finally{groupCompose.disabled=!groupSources.has(product())}};
